-- Biochar Directory Database Seed Script
-- Run with: psql -U postgres -d biochar_db -f seed_database.sql

CREATE TABLE IF NOT EXISTS biochar_companies (
    id SERIAL PRIMARY KEY,
    company_name VARCHAR(255) UNIQUE NOT NULL,
    product_service TEXT,
    benefit_usp TEXT,
    web_youtube_link TEXT,
    opportunities TEXT,
    geographical_coverage TEXT,
    contact TEXT,
    source VARCHAR(50) DEFAULT 'guide',
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    verification_status VARCHAR(50) DEFAULT 'PENDING',
    companies_house_number VARCHAR(50),
    companies_house_status VARCHAR(50),
    verification_notes TEXT,
    verified_at TIMESTAMP,
    ai_confidence VARCHAR(20),
    ai_reasoning TEXT
);

CREATE TABLE IF NOT EXISTS biochar_news (
    id SERIAL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    chunk_text TEXT NOT NULL,
    url VARCHAR(255) NOT NULL,
    embedding TEXT NOT NULL,
    publish_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

