INSERT INTO biochar_news (title, chunk_text, url, embedding, publish_date) VALUES ('Trend watch: Soil carbon MRV & incentives in 2026 — signals, win…', 'urchased by major corporate buyers including JPMorgan Chase, Boston Consulting Group, and Shopify''s Sustainability Fund. The program demonstrates that technology-driven MRV can achieve costs below $5 per acre for monitoring, a fraction of traditional sampling-only approaches.
