INSERT INTO biochar_news (title, chunk_text, url, embedding, publish_date) VALUES ('[Outokumpu Starts Biocoke Plant to Cut Ferrochrome Emissions]', 'Finnish stainless steel producer Outokumpu has inaugurated a new biocoke agglomeration plant in Tornio with an investment of approximately USD 35 million. The facility processes biochar into biocoke to replace fossil coke in ferrochrome production and could reduce annual carbon dioxide emissions by up to 82,000 tonnes at full capacity. The project supports Outokumpu''s target of cutting value-chain carbon dioxide emissions by 42% by 2030 from 2016 levels.', 'https://news.metal.com/newscontent/104068406-outokumpu-starts-biocoke-plant-to-cut-ferrochrome-emissions', '[0.0117510725, 0.013513477, -0.01148341, -0.013441923, -0.00935827, -0.0063128565, -0.00628582, -0.0028913599, -0.0053180167, -0.04473976, -0.0262753, -0.02437628, 0.008295947, -0.0021952859, -0.0012545029, -0.0049848338, 0.006951269, -0.009829679, 0.007926896, 0.0023100136, 0.0066938456, 0.00029731044, -0.009954329, -0.0034854903, -0.008589338, -0.0024495814, -0.010938002, -0.02454558, 0.011110377, 0.15265597, -0.025577903, -0.008542783, -0.0073542814, -0.0021005564, 0.0023816864, -0.017192254, -0.008145889, 0.0051864116, -0.010081454, -0.031968385, -0.00022367362, 0.013583412, -0.013178787, 0.009298523, 0.0152118, -0.013442376, 0.020917948, 0.006761502, -0.004922037, -0.007842899, -0.005965465, 0.011561031, -0.018860694, 0.0041987193, 0.00821879, 0.0017635268, 0.033413358, -0.007876136, 0.015216792, 0.0032306998, 0.005749034, 0.017968336, 0.016723784, 0.007828893, -0.0061520585, -0.010388142, 0.025710046, -0.026062615, 0.035060123, -0.0011273841, 0.0069296868, -0.027024118, -0.01138846, -0.03336435, 0.0007491712, 0.00170437, 0.0045497473, 0.026215088, -0.01905329, -0.010481607, -0.0072098, -0.019124066, -0.017939534, 0.020712797, -0.0028896998, 0.008362064, 0.0011795164, 0.012274496, -0.0018088906, -0.026348662, -0.012971149, 0.0011221628, -0.0043647997, -0.