INSERT INTO biochar_news (title, chunk_text, url, embedding, publish_date) VALUES ('[SMM Steel] Malaysia HRC Price Edges Higher Despite Weak Downstream Demand', '[Malaysia] Malaysia’s domestic HRC transaction price was heard at around USD 519/tonne EXW, up by about USD 5/tonne from roughly USD 514/tonne last week. Despite the modest increase, market participants reported continued weak downstream demand for both HRC and CRC, with transaction volumes remaining low. Buyers are still purchasing mainly on a need-to-use basis, keeping overall market activity subdued.', 'https://news.metal.com/newscontent/104068394-smm-steel-malaysia-hrc-price-edges-higher-despite-weak-downstream-demand', '[0.008514748, 0.011349207, -0.026300728, -0.021780707, -0.00849881, -0.0037398206, 0.0025400103, -0.0026626845, 0.0004931794, -0.05119772, -0.006512687, -0.017954051, 0.0054838685, -0.008318432, -0.000986434, 0.0058854707, 0.011517237, -0.007462199, -0.008202514, 0.018431125, 0.000285472, 0.0067111207, -0.009322175, -0.011865581, -0.030363202, -0.0050560487, 0.004070303, -0.01591698, 0.009994851, 0.11832078, -0.00744553, 0.00342551, 0.0027228047, -0.0023118812, 0.023388619, -0.0020019684, 0.008640724, -0.040879987, -0.015540549, 0.022968752, 0.016810594, 0.023122054, -0.012024875, 0.012934842, 0.011968135, -0.00022642281, 0.0220909, 0.016836228, -0.010914672, 0.0059691537, -0.028542265, 0.0072769932, 0.01904438, 0.03017395, -0.016475178, 0.021440469, -0.016859354, 0.008304094, 0.020985804, 0.0016971856, 0.0015032379, 0.012179435, 0.012883843, 0.010027714, -0.021132957, -0.0067997035, 0.015880782, 0.0014993323, 0.005011942, 0.013976239, -0.0014078532, -0.0130691165, -0.0013923781, 0.0041732113, 0.0035330248, 0.007514118, 0.004151937, 0.008071825, -0.013260389, 0.010312726, -0.039058316, -0.00412676, -0.005053247, 0.011921702, 0.0032460645, 0.0169953, 0.01845523, 0.009902583, -0.015419915, -0.021008134, -0.010836725, -0.018127158, 0.014276449, -0.022270612, -0.01679162, 0.02771759, -0.008