INSERT INTO biochar_news (title, chunk_text, url, embedding, publish_date) VALUES ('[SMM Stainless Steel Flash] POSCO Sells Zhangjiagang and Qingdao Plants to Tsingshan Holding Group', 'oduced via the EAF/AOD route, embedded emissions are calculated at 1.783 mt CO₂/mt; a hypothetical 2027 import of 100mt of stainless steel results in an obligation to surrender 95.9 CBAM certificates after the free-allocation adjustment. Material losses from cutting and machining increase embedded emissions per tonne of finished goods, with stainless steel screws and nuts reaching 2.371 mt CO₂/mt. The guidance is explanatory rather than legally binding, with applicable EU legislation taking precedence.', 'https://news.metal.com/newscontent/104066916-smm-stainless-steel-flash-posco-sells-zhangjiagang-and-qingdao-plants-to-tsingshan-holding-group', '[0.0065199467, -0.017609559, -0.018094558, -0.010657297, 0.0041863485, -0.0044351537, -0.012809328, 0.0041343276, -0.019449344, -0.052984007, -0.018234627, -0.019929519, -0.017116385, -0.033180255, -0.0018967143, 0.0077994093, 0.03291462, -0.028915426, -0.0012992896, 0.006480492, 0.018535836, -0.017331246, -0.0082426, -0.003394399, -0.02743203, 0.01213026, 0.0045584003, -0.0054300926, 0.009013767, 0.1457137, -0.017693512, -0.021332147, -0.005652621, -0.009507335, 0.0010273946, -0.007760955, 0.01043079, -0.015052666, -0.0029850502, -0.012937093, -0.00021289261, 0.01045843, -0.015671473, 0.0129332915, -0.015041515, -0.008846255, 0.02038659, 0.007865565, -0.013663189, -0.005567491, -0.02032798, 0.00868011, 0.023930203, 0.0057524904, -0.013612531, 0.00251464, 0.0023879153, 0.025133323, 0.023581289, -0.0035085306, -0.018941985, 0.002426077, 0.018233342, 0.023407506, 0.008525659, -0.015140046, 0.022060672, -0.03619597, 0.017700203, 0.007882405, 0.014422603, -0.014997783, -0.010908587, -0.014365595, 0.020648811, -0.025869671, -0.011375266, -0.0063556805, -0.0031372, 0.005697792, 0.00259818, 0.012558002, -0.02962039, 0.02303207, -0.008507452, 0.017